  AND EXISTS (SELECT 1 FROM "product_options" o WHERE o.product_slug = p.slug)
  AND NOT EXISTS (SELECT 1 FROM "product_options" o WHERE o.product_slug = p.slug AND o.price <= 0);--> statement-breakpoint
-- (4) Tồn đầu kỳ 10 cho mỗi quy cách đang 0, vào kho mặc định — ghi lô + lịch sử kho như nhập ở admin.
WITH st AS (SELECT id FROM "stores" ORDER BY is_default DESC, id LIMIT 1),
tgt AS (
  SELECT o.product_slug, o.idx FROM "product_options" o, st
  WHERE o.stock = 0 AND o.price > 0 AND o.product_slug IN ('kim-tien', 'luoi-ho', 'trau-ba', 'trau-ba-de-vuong', 'phat-tai', 'van-nien-thanh', 'cau-tieu-tram', 'ngu-gia-bi', 'duoi-cong', 'phu-quy', 'hong-mon', 'sen-da', 'xuong-rong-mini', 'ngoc-ngan', 'duong-xi', 'phat-loc', 'tung-bong-lai', 'lan-quan-tu', 'van-loc', 'truong-sinh', 'hoa-giay', 'loc-vung', 'kim-quyt', 'dam-but', 'hoa-muoi-gio', 'cam-tu-mai', 'ngoc-but', 'ti-gon', 'chuoi-mo-ket', 'chuoi-re-quat', 'van-tue', 'cau-vang', 'bach-trinh-bien', 'co-lan-chi', 'thien-dieu', 'cay-sen', 'sung-kieng', 'kim-giao', 'bach-tan', 'cha-la-canh', 'sao-den', 'dau-rai', 'xa-cu', 'long-nao', 'bang-lang', 'phuong-vi', 'me-tay', 'hoa-sua', 'cau-vua', 'tung-la-han', 'cay-co', 'bang-ta', 'me-ta', 'o-moi', 'bang-vuong', 'bo-de', 'phi-lao', 'so-do-cam', 'kim-ngan', 'bach-ma-hoang-tu', 'trau-ba-de-vuong-xanh', 'trau-ba-de-vuong-do', 'trau-ba-la-xe', 'monstera', 'luoi-ho-vang', 'lan-y', 'thiet-moc-lan', 'phat-tai-nui', 'phat-tai-khuc', 'dai-phu-gia', 'hanh-phuc', 'cau-hawai', 'cau-nhat', 'co-nhat', 'co-ta', 'truc-nhat', 'truc-may', 'truc-bach-hop', 'ngu-gia-bi-vang', 'duoi-phung', 'ngan-hau', 'thanh-tam', 'van-nien-thanh-leo-cot', 'thuong-xuan', 'nha-dam', 'ngoc-bich', 'nhat-mat-huong', 'cam-nhung', 'tung-thom', 'tuyet-tung', 'phong-loc-hoa', 'huyet-du', 'hong-phat-tai', 'dai-de-vuong', 'bang-singapore', 'kim-tien-mini', 'kim-ngan-mini', 'luoi-ho-mini', 'luoi-ho-vang-mini', 'trau-ba-xanh', 'trau-ba-vang', 'trau-ba-cam-thach', 'trau-ba-sua', 'hong-mon-mini', 'lan-y-mini', 'ngu-gia-bi-mini', 'duoi-cong-xanh', 'duoi-cong-tim', 'duoi-cong-soc', 'cam-nhung-xanh', 'cam-nhung-do', 'sen-da-nau', 'sen-da-xanh', 'sen-da-do-la', 'sen-da-phat-ba', 'sen-da-kim-cuong', 'sen-da-mong-rong', 'sen-da-hoa-hong', 'xuong-rong-tai-tho', 'xuong-rong-bat-tien', 'xuong-rong-tru', 'xuong-rong-cau', 'nha-dam-mini', 'duong-xi-mini', 'chuoi-ngoc', 'chuoi-hat', 'phat-tai-mini', 'thiet-moc-lan-mini', 'huyet-du-mini', 'truc-phu-quy', 'phat-du', 'thuy-sinh-kim-ti